import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ExternalLink, Github, X, ChevronRight, User, ArrowUpRight, Lock, Sparkles } from 'lucide-react';
import { PROJECTS } from '../constants';
import { Project, ProjectStatus } from '../types';
import SEO from './SEO';

const ProjectCard: React.FC<{ project: Project; onOpen: (p: Project) => void }> = ({ project, onOpen }) => {
  const getStatusColor = (status: ProjectStatus) => {
    switch (status) {
      case ProjectStatus.LIVE: return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      case ProjectStatus.PROTOTYPE: return 'bg-blue-500/10 text-blue-400 border-blue-500/20';
      case ProjectStatus.IN_PROGRESS: return 'bg-slate-500/10 text-slate-400 border-slate-500/20';
      case ProjectStatus.COMPLETED: return 'bg-purple-500/10 text-purple-400 border-purple-500/20';
      default: return 'bg-white/5 text-white border-white/10';
    }
  };

  return (
    <motion.div
      layout
      initial={{ opacity: 0, scale: 0.98 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.98 }}
      whileHover={{ y: -4 }}
      transition={{ duration: 0.3 }}
      className="glass p-5 sm:p-6 rounded-[2rem] flex flex-col h-full group hover:border-blue-500/30 transition-all cursor-pointer relative overflow-hidden"
      onClick={() => onOpen(project)}
    >
      <div className="flex justify-between items-center mb-5">
        <span className={`px-2.5 py-0.5 rounded-lg text-[8px] font-bold uppercase tracking-wider border ${getStatusColor(project.status)}`}>
          {project.status}
        </span>
        <div className="text-slate-600 group-hover:text-blue-400 transition-colors">
          <ChevronRight size={16} />
        </div>
      </div>

      <h3 className="text-xl font-bold mb-3 group-hover:text-blue-400 transition-colors line-clamp-1">{project.title}</h3>
      <p className="text-slate-400 text-sm mb-6 flex-grow line-clamp-3 leading-relaxed opacity-80">{project.description}</p>

      <div className="flex flex-wrap gap-2 mb-8">
        {project.tags.slice(0, 3).map(tag => (
          <span key={tag} className="px-2 py-0.5 rounded-md bg-white/5 text-[8px] text-slate-500 uppercase font-bold whitespace-nowrap border border-white/5">
            {tag}
          </span>
        ))}
      </div>

      <div className="mt-auto space-y-4">
        <div className="pt-4 border-t border-white/5 flex items-center justify-between">
          <div className="text-[10px] text-slate-500 font-medium flex items-center gap-1.5">
            <User size={10} className="text-slate-600" />
            <span className="truncate max-w-[120px]">{project.role}</span>
          </div>
          <span className="text-[9px] text-slate-600 uppercase font-bold tracking-tight">Details</span>
        </div>

        <div className="w-full">
          {project.id === 'ai-voice-agent' ? (
            <div className="w-full py-2.5 rounded-xl bg-white/5 border border-white/10 text-slate-500 text-[10px] font-bold uppercase tracking-widest text-center">
              Coming soon
            </div>
          ) : project.isPrivate ? (
            <div className="w-full py-2.5 rounded-xl bg-white/5 border border-white/10 text-slate-500 text-[10px] font-bold uppercase tracking-widest flex items-center justify-center gap-2">
              <Lock size={12} /> Restricted Access
            </div>
          ) : (
            <div className="w-full py-2.5 rounded-xl bg-blue-500/5 border border-blue-500/30 text-blue-400 text-[10px] font-bold uppercase tracking-widest flex items-center justify-center gap-2 group-hover:bg-blue-500 group-hover:text-white transition-all shadow-lg shadow-blue-900/10">
              Open Project <ArrowUpRight size={12} />
            </div>
          )}
        </div>
